import xml.etree.ElementTree as ET, collections
t = ET.parse('out.drawio'); bad = 0; tot_v = tot_e = links = 0
for d in t.getroot().findall('diagram'):
    root = d.find('mxGraphModel/root'); ids = collections.Counter(); cells = {}
    for el in root:
        ids[el.get('id')] += 1
        c = el if el.tag == 'mxCell' else el.find('mxCell')
        cells[el.get('id')] = c
        if el.tag == 'UserObject' and el.get('link'): links += 1
    dup = [k for k, v in ids.items() if v > 1]
    for k, c in cells.items():
        p = c.get('parent')
        if p and p not in cells: bad += 1; print('parent?', d.get('id'), k, p)
        if c.get('edge') == '1':
            tot_e += 1
            for a in ('source', 'target'):
                if c.get(a) not in cells: bad += 1; print(a, '?', d.get('id'), k)
        elif c.get('vertex') == '1': tot_v += 1
    if dup: bad += 1; print('dup', d.get('id'), dup[:5])
    # page links valid?
pages = {d.get('id') for d in t.getroot().findall('diagram')}
for uo in t.getroot().iter('UserObject'):
    l = uo.get('link')
    if l and l.split(',')[-1] not in pages: bad += 1; print('link?', l)
print('sorun:', bad, '| düğüm:', tot_v, '| kenar:', tot_e, '| sayfa bağlantısı:', links)
print([d.get('name') for d in t.getroot().findall('diagram')])
EOF

