    """Varsa harici araclarla birim denetimi (yoksa sessizce gecer)."""
    araclar = {"fat32": ["fsck.vfat", "-n"], "exfat": ["fsck.exfat", "-n"],
               "ntfs": ["ntfsfix", "-n"], "ext4": ["e2fsck", "-fn"],
               "ext2": ["e2fsck", "-fn"], "hfsplus": ["fsck.hfsplus", "-n"]}
    if fs_key not in araclar:
